// Compact PAL no-input oracle. Object records are PRE-generator inputs;
// generator fields and the row are sampled after composition.
struct RiverLongObjectState {
    std::uint8_t vertical_position{};
    std::uint8_t horizontal_coordinate{};
    std::uint8_t flags{};
    std::uint8_t animated_kind{};
    std::uint8_t base_kind{};
    std::uint8_t left_bound{};
    std::uint8_t right_bound{};
    std::uint8_t animation_count{};
};

struct RiverLongTraceState {
    std::uint16_t step{};
    std::uint8_t phase{}, buffer_index{}, level{};
    std::uint8_t channel_span{}, bank_inset{}, course{};
    RiverRandomState random{};
    std::array<RiverLongObjectState, 12> objects{};
    std::uint8_t object_cursor{};
    bool split_collision_wrap{};
    std::uint8_t cooldown{};
    std::uint8_t active_begin{};
    std::uint8_t special_cursor{};
    std::uint8_t course_transition_sign{};
    std::uint8_t decision_direction{};
    bool parity{};
    std::array<std::uint8_t, 4> object_guides{};
    PackedRiverRow row{};
};

