inline RiverObjectHistory observed_object_history(const RiverLongTraceState& state) {
    RiverObjectHistory result{};
    result.cursor = state.object_cursor;
    result.split_collision_wrap = state.split_collision_wrap != 0;
    for (std::size_t index = 0; index < result.entries.size(); ++index) {
        const auto& object = state.objects[index];
        result.entries[index] = {object.animated_kind, object.base_kind,
                                      object.horizontal_coordinate, false};
    }
    return result;
}

